const items = $input.all().slice(0, 10);
const results = [];
for (const item of items) {
  const d = item.json;
  const title = d.title || '';
  const snippet = (d.contentSnippet || '').replace(/<[^>]*>/g, '').substring(0, 300);
  const prompt = `Translate this English tech article title and summary into natural Japanese. Keep technical terms in English where appropriate.\n\nTitle: ${title}\nSummary: ${snippet}\n\nRespond in JSON format only:\n{"title": "Japanese title here", "summary": "Japanese summary here"}`;
  const geminiBody = JSON.stringify({
    contents: [{ parts: [{ text: prompt }] }],
    generationConfig: { temperature: 0.2, maxOutputTokens: 500 }
  });
  const output = Object.assign({}, d, { geminiBody });
  results.push({ json: output });
}
return results;

const items = $input.all();
const results = [];
for (let i = 0; i < items.length; i++) {
  const geminiResponse = items[i].json;
  const original = $('PrepareHN').all()[i].json;
  let translatedTitle = original.title;
  let translatedSnippet = original.contentSnippet || '';
  try {
    const responseText = geminiResponse.candidates?.[0]?.content?.parts?.[0]?.text || '';
    const jsonMatch = responseText.match(/\{[\s\S]*\}/);
    if (jsonMatch) {
      const parsed = JSON.parse(jsonMatch[0]);
      translatedTitle = parsed.title || translatedTitle;
      translatedSnippet = parsed.summary || translatedSnippet;
    }
  } catch (e) {}
  const rebuilt = Object.assign({}, original);
  delete rebuilt.geminiBody;
  rebuilt.title = translatedTitle;
  rebuilt.contentSnippet = translatedSnippet;
  results.push({ json: rebuilt });
}
return results;

const items = $input.all();
if (items.length === 0) return [];
const articleList = items.map((item, i) => {
  const d = item.json;
  const title = (d.title || '').substring(0, 100);
  const snippet = (d.contentSnippet || d['content:encodedSnippet'] || '').replace(/<[^>]*>/g, '').substring(0, 150);
  const url = d.link || d.url || '';
  const source = url.includes('zenn.dev') ? 'Zenn' : 'HN';
  return `${i + 1}. [${source}] ${title} - ${snippet}`;
}).join('\n');
const prompt = `以下のニュース記事を、この興味プロファイルとの関連度でランク付けしてください。

興味プロファイル:
1. Claude Code実践活用（Skills, Hooks, Agent Teams等）
2. AI批判・問題提起（AI万能論への反論、倫理的課題）
3. 個人開発×低コストスタック（月額0円〜、Hono, Bun, Cloudflare Workers等）
4. セキュリティ事故・実例（APIキー漏洩、認証不備等）
5. ローカルファースト・自己ホスト（クラウド依存しない技術選択）
6. 言語・ランタイム本質検証（比較・検証記事）

記事一覧:
${articleList}

各ソースから上位3件ずつ選んでください。純粋なJSON形式のみで返答（コメントや説明は一切不要）:
{"zenn": [3, 7, 1], "hn": [12, 5, 9]}`;
const geminiBody = JSON.stringify({
  contents: [{ parts: [{ text: prompt }] }],
  generationConfig: { temperature: 0.1, maxOutputTokens: 200 }
});
return [{ json: { geminiBody } }];

const geminiResponse = $input.first().json;
const originalItems = $('WaitBoth').all();
let selected = [];
try {
  const responseText = geminiResponse.candidates?.[0]?.content?.parts?.[0]?.text || '';
  const zennMatch = responseText.match(/zenn[^[]*\[([0-9,\s]+)\]/i);
  const hnMatch = responseText.match(/hn[^[]*\[([0-9,\s]+)\]/i);
  const extract = (m) => m[1].split(',').map(n => parseInt(n.trim())).filter(n => !isNaN(n));
  if (zennMatch) selected = selected.concat(extract(zennMatch));
  if (hnMatch) selected = selected.concat(extract(hnMatch));
} catch (e) {}
const selectedSet = new Set(selected);
return originalItems.map((item, i) => {
  const d = Object.assign({}, item.json);
  d.isTop5 = selectedSet.has(i + 1);
  return { json: d };
});

const allInput = $input.all();
const isZenn = (item) => (item.json.link || item.json.url || '').includes('zenn.dev');
const byTop5 = (a, b) => (b.json.isTop5 ? 1 : 0) - (a.json.isTop5 ? 1 : 0);
const selected = [...allInput.filter(isZenn).sort(byTop5).slice(0, 10), ...allInput.filter(i => !isZenn(i)).sort(byTop5).slice(0, 10)];
const results = [];
for (const item of selected) {
  const d = item.json;
  const title = (d.title || '').substring(0, 200);
  const url = d.link || d.url || '';
  const date = (d.isoDate || d.pubDate || new Date().toISOString()).substring(0, 10);
  const snippet = (d.contentSnippet || d['content:encodedSnippet'] || '').replace(/<[^>]*>/g, '').substring(0, 300);
  const isTop5 = d.isTop5 === true;
  const source = url.includes('zenn.dev') ? 'Zenn' : 'Hacker News';
  if (!title) continue;
  const requestBody = JSON.stringify({
    parent: { database_id: '2ff2570f-e49f-817d-8288-e7c8667641a9' },
    properties: {
      '\u30bf\u30a4\u30c8\u30eb': { title: [{ text: { content: title } }] },
      'URL': { url: url || null },
      '\u30ab\u30c6\u30b4\u30ea': { select: { name: '\u30c6\u30c3\u30af' } },
      '\u30bd\u30fc\u30b9': { rich_text: [{ text: { content: source } }] },
      '\u65e2\u8aad': { checkbox: false },
      '\u6ce8\u76ee': { checkbox: isTop5 },
      '\u65e5\u4ed8': { date: { start: date } },
      '\u8981\u7d04': { rich_text: [{ text: { content: snippet } }] }
    }
  });
  results.push({ json: { requestBody, title, source } });
}
return results;
